select
users.*
from users users

    and users.id = #{id}
    and users.user_name = #{userName}
    and users.pass_word = #{passWord}
    and users.nick_name like concat('%',#{nickName},'%')
    and users.head_img = #{headImg}
    and users.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from users users

    and users.id = #{id}
    and users.user_name = #{userName}
    and users.pass_word = #{passWord}
    and users.nick_name like concat('%',#{nickName},'%')
    and users.head_img = #{headImg}
    and users.create_time = #{createTime}
